#include "unity.h"
#include "buffer.h"
#include "helpers.h"

// Forward declarations for helper types and functions
// (Normally these would be in a header, but are added here for compilation)
typedef struct stdout_capture_t stdout_capture_t;
stdout_capture_t *capture_stdout_start(void);
char *capture_stdout_stop(stdout_capture_t *cap);
void assert_stdout_equals(stdout_capture_t *cap, const char *expected);

void setUp(void) { }
void tearDown(void) { }

void unit_test_buffer_print_prints_hex_output_for_nonempty_buffer(void) {
    // Setup: create a buffer with known data
    // We'll use 10 bytes: 0x01, 0x23, 0x45, 0x67, 0x89, 0xab, 0xcd, 0xef, 0x10, 0x20
    unsigned char test_data[10] = {0x01, 0x23, 0x45, 0x67, 0x89, 0xab, 0xcd, 0xef, 0x10, 0x20};
    buffer_t *buf = buffer_new_with_size(10);
    TEST_ASSERT_NOT_NULL(buf);
    // Copy test data into buffer
    memcpy(buf->alloc, test_data, 10);
    buf->len = 10;

    // Capture stdout
    stdout_capture_t *cap = capture_stdout_start();

    // Test: call buffer_print
    buffer_print(buf);

    // Stop capture and get output
    char *output = capture_stdout_stop(cap);

    // Expected output:
    // First line: "
 "
    // Then 8 bytes: " 01 23 45 67 89 ab cd ef
 "
    // Then 2 bytes: " 10 20
"
    // So, expected string is:
    // "
  01 23 45 67 89 ab cd ef
  10 20
"
    const char *expected =
        "
  01 23 45 67 89 ab cd ef
  10 20
";

    // Assert output matches expected
    assert_stdout_equals(cap, expected);

    // Cleanup
    free(output);
    buffer_free(buf);
}

int main(void) {
    UNITY_BEGIN();
    RUN_TEST(unit_test_buffer_print_prints_hex_output_for_nonempty_buffer);
    return UNITY_END();
}


